<section class="card"><div class="section-heading"><h2>Curse recente</h2><span class="muted"><?=e($total)?> înregistrări</span></div><div class="table-scroll"><table><thead><tr><th>Data / Referință</th><th>Participant</th><th>Tarif</th><th>Credit folosit</th><th>Credit câștigat</th><th>Stare</th></tr></thead><tbody><?php foreach($rides as $r):?><tr><td><a href="?page=ride&amp;id=<?=e($r['id'])?>"><?=e(localtime_ro($r['created_at']))?> ↗<small><?=e(substr($r['id'],0,12))?></small></a></td><td><?=e($r['participant_name'])?><small><?=e($r['vehicle_plate'])?></small></td><td><?=ron($r['fare'])?> lei</td><td><?=ron($r['redeemed'])?> lei</td><td class="positive">+<?=ron($r['earned'])?> lei</td><td><span class="pill"><?=in_array($r['status'],['draft','ready'],true)&&$r['expires_at']<=Alba\App::now()?'Expirat':state($r['status'])?></span></td></tr><?php endforeach ?><?php if(!$rides):?><tr><td colspan="6"><div class="empty">Încă nu există curse. Prima călătorie confirmată apare aici.</div></td></tr><?php endif ?></tbody></table></div><?php pager($total,$offset,$role,$section); ?></section>
